import {S,P,T,D,C,U,refs} from './model.mjs';
export default [
S('Анализ задачи и проектирование информационного ресурса','',P(['Проблема','Что мешает студенту и преподавателю'],['Решения','Какие действия и правила поддерживает система'],['Результат','Паспорт проекта, требования, границы версии']),
'Сегодня мы начинаем дисциплину «Проектирование информационных ресурсов» по специальности 09.02.09 «Веб-разработчик». На первом вебинаре подготовим описание учебного сервиса «Проектный навигатор». Студент выбирает проект и подаёт заявку, преподаватель принимает решение. Мы последовательно получим требования и границы первой версии.',
'Все примеры заранее подготовлены. Основные решения будем разбирать на схемах и таблицах. В конце станет понятно, какие сведения необходимо согласовать до создания экранов и программы.','Титульный слайд. Коротко представьте название дисциплины и результат.'),
S('Информационный ресурс','Организованная информация, которой пользуются для определённой задачи',T(['Ресурс','Содержание','Действие'],[['Каталог библиотеки','Описание изданий','Найти книгу'],['Расписание','Занятия и аудитории','Узнать время'],['Каталог проектов','Темы и условия участия','Выбрать проект']]),
'В рамках нашего курса информационным ресурсом будем называть организованную информацию и способы работы с ней, которые помогают пользователю решить задачу. Файлы с описаниями проектов тоже содержат информацию. Но пользователю важно быстро найти нужное описание, понять условия и получить достоверный результат своего обращения. Поэтому проектирование включает структуру содержания, доступ, поиск и обновление. Название ресурса само по себе ещё не объясняет, кому он нужен. Для каждого примера на экране мы связываем сведения с конкретным действием человека.',
'Если каталог содержит старые темы без отметки о завершении набора, информация может быть формально доступна, но вводить студента в заблуждение. Значит, актуальность входит в проектную задачу вместе с составом данных. Мы рассматриваем ресурс через пользу и наблюдаемое поведение, а затем выбираем техническую реализацию.','Читайте таблицу построчно: содержание, затем действие.'),
S('Типы информационных ресурсов','Способ организации зависит от задачи пользователя',P(['Справочник','Человек получает устойчивые сведения по известному вопросу'],['Каталог','Человек сравнивает несколько объектов и выбирает подходящий'],['Сервис','Человек передаёт данные и получает результат обработки']),
'Разные ресурсы требуют разных проектных решений. На странице с правилами участия достаточно дать понятное содержание и дату обновления. В каталоге проектов понадобятся отдельные карточки, чтобы сравнивать темы. В сервисе подачи заявок появляется изменение данных: система должна принять обращение и сохранить его. Один продукт может объединять эти способы работы. «Проектный навигатор» содержит каталог, но его назначение шире просмотра информации. После выбора проекта студент выполняет действие, результат которого должен увидеть преподаватель.',
'Это различие помогает оценить объём работы. Публикация текста и приём заявок имеют разные требования к правам, подтверждению и хранению. Мы не будем выбирать сложную платформу только потому, что ресурс назван сервисом. Сначала установим, какие действия действительно требуются первой версии.','Показывайте различие по действию, а не по внешнему виду страниц.'),
S('Особенности веб-приложения','Действие в браузере меняет общее состояние системы',D(['Браузер студента','Обработка на сервере','Общие данные'],[['Браузер студента','Обработка на сервере','Действие пользователя'],['Обработка на сервере','Общие данные','Сохранение'],['Обработка на сервере','Браузер студента','Результат']]),
'Веб-приложением будем называть программу, с которой человек работает через браузер. Браузер показывает интерфейс и передаёт действия пользователя. Сервер принимает обращения и выполняет правила. Общие данные сохраняются так, чтобы результат не зависел от того, оставил ли студент страницу открытой. Пока это только обзор устройства: подробный обмен запросами разберём на третьем занятии. Здесь важно увидеть, почему изменение надписи на экране ещё не означает, что система приняла заявку.',
'Представим, что после нажатия кнопки появилась зелёная плашка, а преподаватель ничего не получил. Пользовательское действие выглядело завершённым, но задача осталась нерешённой. Поэтому проектировщик описывает не только экран. Он определяет, какие данные должны сохраниться и кто получит к ним доступ.','Начните с браузера, затем пройдите по подписанным связям.'),
S('Учебный сервис «Проектный навигатор»','Один пример проходит через все четыре вебинара',T(['Участник','Учебные данные','Цель'],[['Студент','Анна Смирнова, id 12','Подать заявку'],['Преподаватель','Ирина Павлова, id 7','Принять решение'],['Проект','Сайт студенческого клуба, id 17','Набрать участников']]),
'Во всех занятиях будем использовать одинаковые учебные сведения. Анна Смирнова выбирает проект «Сайт студенческого клуба». За проект отвечает Ирина Павлова. Числа двенадцать, семь и семнадцать служат идентификаторами, то есть обозначают конкретные записи. Они не задают порядок участия и не являются паролями. После успешного создания заявка Анны получит номер сто четыре. До этого события такой заявки в наших исходных данных нет. Сохраним этот порядок, когда дойдём до экранов и запросов.',
'Наш сервис учебный, а данные условные. Он нужен для проверки связности решений: одна и та же заявка сначала появится как пользовательский сценарий, затем как объект данных и серверная операция. Смена предмета рассмотрения позволит углублять пример без повторного знакомства с героями.','Произнесите имена и номера. Не представляйте макеты как работающий сервис.'),
S('Исходная проблема','Заявки распределены между сообщениями и таблицами',T(['Источник','Запись','Сложность'],[['Сообщение Анны','Хочу участвовать в клубном сайте','Нет общего номера'],['Личная таблица','Анна, клубный сайт','Неясно, внесена ли заявка'],['Сообщение преподавателя','Пришлите сведения повторно','Возникает второй экземпляр']]),
'Начнём с ситуации до автоматизации. Анна пишет преподавателю в сообщениях. Преподаватель переносит сведения в личную таблицу, а позже получает уточнение ещё в одном диалоге. На каждом шаге люди знают только часть истории. Чтобы ответить, принята ли заявка, приходится сопоставлять переписку и таблицу. Такие затруднения не означают, что участники невнимательны. Сам процесс требует ручного переноса и не даёт единого места для проверки результата.',
'На экране показана условная ситуация, а не исследование конкретной организации. Из неё мы выделяем наблюдаемые трудности. Пока рано писать требование «сделать удобный сайт»: оно пропускает причину затруднений. Сначала определим, в каком месте информация расходится и какое действие пользователь хочет подтвердить.','Разберите каждую строку как отдельное свидетельство проблемы.'),
S('Сбор заявок через сообщения','Отправитель и получатель по-разному понимают завершение действия',P(['Анна отправила текст','Для неё обращение уже передано'],['Ирина прочитала сообщение','Для неё сведения ещё предстоит перенести'],['Запись попала в таблицу','Только теперь появляется общий рабочий список']),
'В сообщениях нет единого момента, который оба участника считают регистрацией заявки. Анна видит, что текст отправлен. Ирина может прочитать его между занятиями и запланировать перенос на вечер. Если студент спрашивает о результате раньше, ответы будут противоречивыми. Проблема состоит в различии между передачей сообщения и появлением учтённого обращения. При проектировании нам понадобится явный признак: заявка сохранена и доступна в соответствующем списке.',
'Прочтение сообщения не следует превращать в отдельный статус заявки нашего сервиса. Это событие исходного процесса. В будущей модели зафиксируем только те состояния, которые нужны для рассмотрения: начальное ожидание и два результата решения. Тем самым мы улучшаем учёт, не воспроизводя каждую особенность переписки.','Различайте исходный процесс и правила будущей системы.'),
S('Потерянное обращение','Отправленное сообщение отсутствует в общем списке',P(['Наблюдение','Анна отправила сведения, но в таблице её строки нет'],['Последствие','Преподаватель не учитывает обращение при рассмотрении'],['Потребность','Участники должны видеть подтверждённую регистрацию']),
'Слово «потерялась» слишком общее для разработки. Уточним наблюдение: сообщение существует, но в рабочем списке заявки нет. Оно могло остаться в другом диалоге или не попасть в таблицу при переносе. Причины отличаются, однако неудобство для пользователя одинаково: нет подтверждения, что обращение принято к рассмотрению. На этой основе позже сформулируем требование к сохранению и отображению. Пока фиксируем проблему без догадки о том, какой именно программный модуль нужно написать.',
'Такое уточнение делает обсуждение предметным. Можно предъявить отправленное сообщение и отсутствие строки. Фразу «пользователям некомфортно» проверить гораздо сложнее. Мы постепенно переводим переживание человека в наблюдаемую ситуацию, сохраняя его исходную потребность.','Прочитайте формулировку наблюдения целиком.'),
S('Повторные заявки','Один студент и один проект оказываются в списке несколько раз',T(['Студент','Проект','Основание записи'],[['Анна Смирнова','Сайт студенческого клуба','Первое сообщение'],['Анна Смирнова','Сайт студенческого клуба','Повтор после отсутствия ответа'],['Анна Смирнова','Другой проект','Самостоятельная допустимая заявка']]),
'Повтор возникает не только из-за случайного двойного нажатия. В исходном процессе студент не получил подтверждение и отправил сведения снова. Если преподаватель перенесёт оба сообщения, число заявок увеличится без появления второго участника. Но совпадение имени само по себе недостаточно для запрета. Один студент может интересоваться разными проектами. Поэтому наше правило относится к сочетанию студента и проекта. На другой проект Анна вправе подать отдельную заявку.',
'Обратите внимание на третью строку. Она выглядит похожей, но не является дубликатом. В проектировании ограничение должно точно описывать запрещённую ситуацию. Слишком широкий запрет закроет допустимое действие, слишком узкий оставит повторы. Позже свяжем это правило с двумя идентификаторами в данных.','Сопоставьте первую и вторую строки, затем отдельно третью.'),
S('Неясный статус','Участник не может отличить ожидание от принятого решения',T(['Фраза в переписке','Возможное понимание','Что нужно уточнить'],[['Посмотрим позже','Заявку ещё не рассматривали','Есть ли зарегистрированная заявка'],['Вы подходите','Участие одобрено','Принято ли окончательное решение'],['Набор завершён','Отказ всем или закрытие новых заявок','Что произошло с уже поданными']]),
'Свободные сообщения удобны для разговора, но плохо заменяют согласованные состояния. Студент может принять предварительный комментарий за окончательное одобрение. Закрытие набора может означать запрет новых обращений, а не автоматический отказ всем участникам. Нам нужен общий словарь состояния заявки. В первой версии это «На рассмотрении», «Одобрена» и «Отклонена». Состояние проекта «закрыт» относится к приёму новых заявок и хранится отдельно.',
'Разделение двух объектов предотвращает скрытую ошибку. Когда проект закрыли, уже сохранённая заявка не исчезает и не обязана менять решение. Такие последствия должны вытекать из явно согласованного правила. В нашем учебном варианте закрытие только останавливает новые подачи.','Не добавляйте «Закрыта» к статусам заявки.'),
S('Причины затруднений','Ручной перенос и отсутствие общего подтверждения создают расхождения',P(['Разрозненные источники','Часть сведений хранится в сообщениях, часть в таблицах'],['Ручная регистрация','Отправка и учёт происходят в разное время'],['Неопределённые правила','Нет общего понимания повторов и решений']),
'Теперь можем связать наблюдения с устройством процесса. Потери возникают там, где человеку нужно перенести сведения. Повторы усиливаются из-за отсутствия подтверждения. Неясные статусы поддерживает свободная формулировка результата. Для каждой причины потребуется своё проектное решение. Единое хранилище не исправит неопределённые правила решения преподавателя. Красивый экран не заменит подтверждение сохранения. Анализ нужен, чтобы не пытаться исправить всё одной внешней переменой.',
'Мы не доказываем, что любой ручной процесс плох. Для маленькой разовой группы таблица может быть достаточной. В этом учебном случае нужны согласованный учёт и доступ участников к своему результату. Именно эти потребности оправдывают создание сервиса и задают его границы.','Свяжите каждую причину с ранее разобранной трудностью.'),
S('Ожидаемый результат автоматизации','Зарегистрированная заявка видна обеим сторонам в пределах их прав',P(['Студент','Видит свою заявку и актуальный результат рассмотрения'],['Преподаватель','Видит заявки на собственные проекты'],['Система','Хранит одну заявку для пары студент и проект']),
'Автоматизация должна изменить наблюдаемую ситуацию. После подачи Анна видит заявку в разделе «Мои заявки». Ирина видит её в списке своего проекта. Если Анна повторяет отправку, в системе не появляется вторая запись. Это уже конкретные ориентиры. Мы пока не задаём внешний вид кнопок или выбранный язык программирования. Ожидаемый результат можно описать независимо от инструментов реализации. Такое описание помогает согласовать задачу до технических затрат.',
'Важно сохранить границу доступа. Общий учёт не означает общий публичный список мотивационных текстов. Студент получает свои обращения, преподаватель — обращения на собственные проекты. Полезное изменение процесса должно учитывать не только наличие информации, но и того, кому она показывается.','Сначала назовите результат каждой роли, затем общее ограничение.'),
S('Граница системы','В первую версию входит полный путь заявки',T(['Внутри сервиса','Вне первой версии'],[['Каталог и карточка проекта','Создание проектов через редактор'],['Подача и свои заявки','Чат и видеовстречи'],['Решение преподавателя','Автоматический подбор'],['Заранее подготовленный вход','Разработка механизма регистрации']]),
'Граница системы показывает, за что отвечает создаваемый продукт. Мы включаем каталог, подачу и рассмотрение заявки. Каталог заранее заполнен учебными проектами. Вход считаем действующим: на следующих занятиях сервер сможет определить пользователя по сеансу. Это допущение позволяет разобрать проектирование заявки без отдельного курса по регистрации. Однако существование входа не даёт права доверять любому номеру пользователя, переданному в форме.',
'Вне границы первой версии остаются чат, видеовстречи и подбор проектов. Это не навсегда запрещённые функции. Они просто не нужны для завершения основного пути. Явная граница защищает материалы от случайного появления новых полей и полномочий, которые никто не проектировал.','Уточните допущение о готовом входе.'),
S('Пользователи и их цели','В сервисе действуют две роли',T(['Роль','Цель','Действия'],[['Студент','Получить участие в выбранном проекте','Каталог, заявка, свой статус'],['Преподаватель','Набрать участников своего проекта','Просмотр обращений, решение']]),
'Роль описывает характер взаимодействия с системой. Один реальный человек в разных продуктах может выполнять разные роли, но наш учебный пример фиксирует только две. Студент ищет проект и отслеживает своё обращение. Преподаватель рассматривает обращения на свои проекты. Список действий следует из целей. Если действие не связано с целью, необходимо понять, зачем оно появляется. Например, редактирование чужой заявки не требуется ни одной из этих ролей.',
'Не будем вводить администратора только потому, что он встречается во многих приложениях. Поддержка сервиса как техническая работа существует, но отдельный пользовательский кабинет сопровождения в первой версии не проектируется. Это помогает сохранить понятную модель доступа и не подменять действующие роли организационными должностями.','Отделяйте роль в приложении от должности человека.'),
S('Заинтересованные стороны','На решения влияют и те, кто не работает с интерфейсом',P(['Пользователь','Анна непосредственно подаёт заявку через сервис'],['Преподаватель','Ирина задаёт условия рассмотрения своего проекта'],['Координатор учебных проектов','Заинтересован в понятном процессе и результатах внедрения']),
'Заинтересованная сторона — человек или группа, чьи интересы затрагивает система. Пользователь непосредственно взаимодействует с интерфейсом и тоже относится к заинтересованным сторонам. Координатор может согласовывать правила организации процесса, не получая собственной учётной записи в нашей модели. Поэтому перечень заинтересованных сторон шире перечня ролей. Мы используем его для сбора требований, а не для автоматического создания новых экранов.',
'Предположим, координатор просит единые названия статусов во всех проектах. Такое пожелание влияет на правила и словарь интерфейса. Из него не следует, что координатору обязательно нужен кабинет с правом менять заявки. Полномочия проектируют отдельно, когда появляется подтверждённый сценарий.','Третья позиция не является третьей ролью приложения.'),
S('Внешнее окружение','Система получает действия участников и работает в учебном процессе',D(['Студент','Проектный навигатор','Преподаватель','Учебный процесс'],[['Студент','Проектный навигатор','Выбор и подача'],['Проектный навигатор','Студент','Подтверждение и статус'],['Преподаватель','Проектный навигатор','Решение'],['Учебный процесс','Проектный навигатор','Согласованные правила']]),
'Окружение включает участников и условия, с которыми соприкасается ресурс. На этой схеме мы рассматриваем систему как единое целое. Внутри пока не рисуем браузер, сервер и базу. Нас интересует, откуда поступают действия и кому нужен результат. Учебный процесс определяет смысл выбора проекта и рассмотрения обращения. Он не является программным сервисом, которому нужно отправлять сетевой запрос. Связь здесь обозначает влияние правил.',
'Такой уровень описания полезен в начале обсуждения. Люди могут согласовать взаимодействия без технической терминологии. Если в окружении появляется внешняя организация или сервис, потребуется отдельно описать обмен. В нашей первой версии уведомления ещё не включены. Они появятся как расширение на четвёртом занятии.','Проговорите смысл каждой подписи связи.'),
S('Контекстная схема','Один блок системы и подписанные взаимодействия с двумя ролями',D(['Анна: студент','Проектный навигатор','Ирина: преподаватель'],[['Анна: студент','Проектный навигатор','Проект и мотивация'],['Проектный навигатор','Анна: студент','Мои заявки и статус'],['Ирина: преподаватель','Проектный навигатор','Одобрение или отказ'],['Проектный навигатор','Ирина: преподаватель','Заявки своих проектов']]),
'Контекстная схема показывает границу системы и её взаимодействия с внешними участниками. Слева Анна передаёт выбранный проект и мотивационный текст. В ответ она получает подтверждение и сведения о своих заявках. Справа Ирина получает обращения к собственным проектам и передаёт решение. Подписи делают связи содержательными. Линия без названия не объясняет, что пересекает границу. Поэтому мы читаем не только прямоугольники, но и направление каждого обмена.',
'Эта схема не задаёт число страниц и не описывает последовательность нажатий. Она отвечает на более общий вопрос: кто взаимодействует с ресурсом и что получает. Дальше мы дополним её процессом, где будет виден порядок действий и ответственность участников.','Не называйте эту схему архитектурой размещения.'),
S('Текущий процесс','Результат зависит от переноса сведений между источниками',P(['Анна пишет сообщение','Передаёт проект и мотивацию в личный диалог'],['Ирина переносит сведения','Создаёт строку в своей таблице'],['Ирина принимает решение','Оставляет отметку и отправляет новое сообщение'],['Анна ищет ответ','Сверяет переписку, если подтверждение непонятно']),
'Процесс — последовательность действий, которая приводит к результату. Здесь сначала действует студент, затем преподаватель. Перенос в таблицу является отдельным шагом, у которого нет общего видимого подтверждения. Решение тоже передаётся отдельно от записи. Если одно сообщение пропущено, картина у участников расходится. Мы выделяем шаги не для обвинения исполнителей, а для понимания зависимости между действиями. Именно в точках ручной передачи возникают трудности учёта.',
'Можно улучшить инструкцию по переписке, но останется необходимость сопоставлять источники. Наш вариант автоматизации меняет место регистрации: студент передаёт данные сразу в общий сервис, а преподаватель работает с сохранённой записью. Следующий слайд покажет этот вариант целиком.','Называйте исполнителя перед каждым действием.'),
S('Предлагаемый процесс','Сохранённая заявка связывает подачу и решение',P(['Анна выбирает проект','Открывает карточку и заполняет мотивацию'],['Система сохраняет заявку','Показывает Анне состояние «На рассмотрении»'],['Ирина рассматривает обращение','Открывает список собственного проекта'],['Система сохраняет решение','Показывает Анне «Одобрена» или «Отклонена»']),
'В предлагаемом процессе исчезает ручная регистрация сообщения. После заполнения формы система проверяет правила и сохраняет заявку. Именно сохранение позволяет обеим сторонам работать с одним обращением. Преподаватель не создаёт вторую копию мотивационного текста, а открывает уже существующую заявку. Решение меняет её состояние. Студент затем получает актуальные сведения в своём разделе. Для этого не требуется, чтобы два участника одновременно находились на сайте.',
'На схеме показан основной успешный путь. Возможные отказы мы разберём отдельно: текст может быть слишком коротким, проект закрытым, а заявка повторной. Основная последовательность остаётся опорой, относительно которой удобно объяснять такие ветви.','Покажите, где впервые возникает запись заявки.'),
S('Чтение модели процесса','Порядок действий, исполнитель и наблюдаемый результат',T(['Элемент модели','Как читаем','Пример'],[['Шаг','Кто выполняет действие','Система сохраняет заявку'],['Порядок','Что должно произойти раньше','Сохранение перед подтверждением'],['Результат','Что изменилось после шага','Заявка видна Анне'],['Исключение','Когда путь прерывается','Проект закрыт']]),
'Модель полезна, когда разные читатели одинаково понимают изображённое. Для каждого шага называем исполнителя, действие и результат. Затем проверяем порядок: нельзя честно подтвердить сохранение раньше, чем оно завершилось. Отдельно отмечаем условия, при которых основной путь не продолжается. Если модель показывает только слова «заявка» и «решение» без действий, она описывает понятия, но ещё не объясняет процесс. При чтении мы связываем каждый элемент с конкретным событием.',
'Схема устройства отвечает на другой вопрос: из каких частей состоит приложение. На ней браузер и база могут находиться рядом, но это не означает их прямое взаимодействие. Поэтому всегда сначала устанавливаем назначение модели. Так можно избежать ошибочных выводов из внешне похожих прямоугольников и линий.','Сопоставьте модель процесса с контекстной схемой.'),
S('Требование к системе','Согласованное описание необходимого поведения или свойства',P(['Потребность','Анна хочет убедиться, что обращение принято'],['Требование','Система сохраняет заявку и показывает её студенту'],['Проверка','После подачи в своих заявках видна нужная запись']),
'Требование фиксирует, что система должна делать или каким свойством обладать. Оно появляется из потребности, но формулируется достаточно точно для проектирования и проверки. Фраза «заявки не должны теряться» задаёт направление, однако оставляет открытым момент регистрации. Мы уточняем действие системы и видимый результат. Требование не обязано сразу описывать таблицу базы или конкретную библиотеку. Такие детали выбирают на основе задачи и ограничений.',
'Представим, что разработчик сохранил сведения, но не показал их Анне. Одна часть потребности выполнена, другая остаётся нерешённой. Поэтому состав требования нужно читать полностью. Удобно отделять обязательное поведение от способа реализации, чтобы техническая замена не разрушала смысл договорённости.','Подчеркните связь между потребностью и проверяемым поведением.'),
S('Источники требований','Высказывание подтверждают наблюдением и примером',T(['Источник','Что узнаём','Ограничение'],[['Разговор с Анной','Она не видит подтверждение','Нужен конкретный случай'],['Рабочая таблица Ирины','Как учитывают обращения','Таблица может быть неполной'],['Наблюдение процесса','Где переносят сведения','Один случай не описывает все ситуации']]),
'Источником требования может быть разговор, документ или наблюдение за работой. Каждый источник показывает свою часть задачи. Анна хорошо описывает затруднение с подтверждением, но не обязана знать, как преподаватель ведёт список. Таблица показывает поля, однако не всегда объясняет их смысл. Поэтому важные сведения сопоставляют. Если в разговоре звучит запрет нескольких проектов, а текущие правила их разрешают, противоречие необходимо разрешить до реализации.',
'Для учебного курса согласованный промпт служит источником правил «Проектного навигатора». В реальном проекте понадобится зафиксировать, кто утвердил спорное решение и на каких данных оно основано. Номер требования позволит связать последующие экраны и проверки с этой договорённостью.','Не представляйте учебную ситуацию как проведённое интервью.'),
S('Функциональные требования','Какие действия выполняет ресурс',T(['Код','Поведение'],[['ФТ-01','Сохранение и показ своей заявки'],['ФТ-02','Каталог и карточка проекта'],['ФТ-03','Просмотр заявок собственного проекта'],['ФТ-04','Однократное итоговое решение преподавателя']]),
'Функциональное требование описывает действие или результат работы системы. В нашем примере система получает каталог, принимает заявку, показывает обращения и сохраняет решение. Для удобства назначим требованиям обозначения. Буквы ФТ означают «функциональное требование», число отличает одну запись от другой. Нумерация не означает важность. Она помогает сослаться на конкретное поведение при обсуждении макета, серверного обработчика или проверки.',
'Строки на экране пока являются краткими названиями. У полного требования будут условия и признаки выполнения. Например, ФТ-03 должно учитывать принадлежность проекта преподавателю. Без этого уточнения «просмотр заявок» легко превратится в доступ ко всем обращениям, хотя такого права мы не согласовывали.','Расшифруйте ФТ перед первым чтением кода.'),
S('Требования к качеству','Как оценивают выполнение полезного действия',T(['Область','Условие','Признак'],[['Доступность формы','Работа с клавиатурой','Доступны поле и кнопка, виден фокус'],['Понятность','Текст короче минимума','Названы граница и способ исправления'],['Надёжность учёта','Повторная отправка','Вторая заявка не создаётся']]),
'Кроме набора функций важны свойства их выполнения. Форма может существовать, но быть недоступной с клавиатуры. Сообщение об ошибке может появляться, но не объяснять, что исправить. Требования к качеству уточняют, каким должен быть результат в заданных условиях. Некоторые свойства пересекаются с правилами поведения. Это допустимо, если их смысл и способ проверки ясны. Не нужно спорить о категории ценой потери существенного ограничения.',
'Здесь мы не обещаем конкретную скорость загрузки без условий измерения. Для такого требования понадобятся объём данных, нагрузка и граница времени. На четвёртом занятии появится подготовленный пример измерений. Сейчас важно увидеть разницу между наличием функции и пригодностью её выполнения для пользователя.','Не добавляйте вымышленные показатели доступности сервиса.'),
S('Измеримость требования','Условия и результат позволяют проверить договорённость',T(['Расплывчато','Проверяемо'],[['Форма должна быть удобной','Поле подписано, ограничение видно до отправки'],['Заявка отправляется быстро','Время измеряют для указанной нагрузки и объёма данных'],['Статус всегда понятен','В списке показан один из трёх согласованных статусов']]),
'Измеримость означает возможность определить, выполнено ли требование. Это не обязательно число. Наличие подписи или конкретного статуса тоже проверяется наблюдением. Уточнение начинается с условий: кто действует, с какими данными и в каком состоянии системы. Затем описывается ожидаемый результат. Если требование использует слова «быстро» или «удобно», необходимо раскрыть их смысл для данного сценария. Иначе разные участники будут оценивать результат по разным основаниям.',
'Пример со скоростью на экране специально оставляет числовую границу несогласованной. Мы показываем состав измеримого условия, а не выдаём случайное число за утверждённое требование. После измерений команда сможет обосновать целевой показатель и условия его проверки.','Различайте проверяемость наблюдением и числовое измерение.'),
S('Разбор жалобы о потерянных заявках','Наблюдение превращается в действие и подтверждение',P(['Наблюдение','Сообщение отправлено, строки в рабочем списке нет'],['Цель Анны','Убедиться, что её обращение зарегистрировано'],['Цель Ирины','Увидеть новое обращение в своём проекте'],['Решение','Сохранить заявку и показать обеим сторонам допустимые сведения']),
'Разберём жалобу «Нужно, чтобы заявки больше не терялись». Первым шагом уточняем наблюдение: отправленное обращение отсутствует в общем списке. Вторым выясняем, что Анна считает завершением подачи. Ей необходимо увидеть зарегистрированную заявку. Третьим учитываем преподавателя: Ирина должна получить запись для рассмотрения. Теперь можно описать действие системы. Она сохраняет заявку и предоставляет доступ по роли. Так из жалобы получается согласованное поведение.',
'Здесь полезно проверить причинную связь. Простая надпись «Отправлено» не гарантирует сохранения. Сообщение преподавателю тоже не заменяет запись. Для приёмки нужен результат, который можно повторно получить из системы. Поэтому выбранный признак связан с разделом «Мои заявки», а не только с краткой плашкой после нажатия.','Пройдите четыре шага без предложения аудитории решить задачу.'),
S('Критерий приёмки ФТ-01','После успешной подачи заявка видна в своём списке',T(['Элемент','Заполненное описание'],[['Исходные условия','Анна вошла, проект 17 открыт, заявки ещё нет'],['Действие','Передан мотивационный текст допустимой длины'],['Результат','В «Моих заявках» виден проект 17 и «На рассмотрении»'],['Обозначение','ФТ-01: сохранение и отображение своей заявки']]),
'Критерий приёмки задаёт признак, по которому принимают результат работы. В нашем случае недостаточно увидеть новую строку где угодно. Она должна относиться к Анне, указывать выбранный проект и содержать начальное состояние. Условие отсутствия предыдущей заявки тоже важно: иначе мы случайно проверим повторную подачу. Вход в систему принимаем действующим. Длина мотивации находится между пятьюдесятью и тысячей символов включительно.',
'Успешность в этом примере означает сохранение обращения, а не одобрение участия. Решение преподавателя будет отдельным действием. Такое разделение помогает и при разработке, и при последующей проверке: можно точно указать, какая часть сценария дала неправильный результат.','Читайте исходные условия перед ожидаемым результатом.'),
S('Реестр требований','Каждая договорённость имеет обозначение и связь с результатом',T(['Код','Условие','Признак выполнения'],[['ФТ-01','Корректная первая подача','Своя заявка со статусом pending'],['ПР-01','Повтор той же пары','Вторая запись отсутствует'],['ПР-02','Длина мотивации','Допустимо 50–1000 символов'],['ПР-03','Решение преподавателя','Только свой проект, исходный статус pending']]),
'Реестр — это упорядоченный список согласованных требований и правил. Здесь добавлены обозначения ПР, то есть «правило проекта». Они помогают различать пользовательское действие и ограничения его выполнения. Внутреннее слово pending соответствует надписи «На рассмотрении». Мы впервые фиксируем это соответствие, чтобы позднее данные и экран не разошлись. Полный словарь трёх состояний появится в блоке о данных.',
'Реестр не должен превращаться в перечень несвязанных обещаний. Для каждой строки известен сценарий применения и признак выполнения. Если на следующем занятии макет позволит отправить десять символов без ошибки, мы сможем сослаться на ПР-02. Обозначение делает замечание адресным и облегчает исправление всех связанных материалов.','Расшифруйте ПР. pending произносится «пэндинг».'),
S('Основной сценарий подачи','Предусловия, действие и сохранённый результат',P(['Предусловия','Анна вошла, проект открыт, предыдущей заявки нет'],['Заполнение','Анна вводит мотивацию длиной 50–1000 символов'],['Приём','Система проверяет условия и сохраняет заявку'],['Завершение','В своих заявках Анна видит «На рассмотрении»']),
'Сценарий описывает последовательность взаимодействия для достижения цели. Начинаем с предусловий, то есть сведений, которые должны быть верны до начала действия. Затем Анна заполняет форму. Система проверяет значения и правила, после чего сохраняет запись. Завершение мы определяем по доступному результату: заявка видна в своём списке. Это основной путь, в котором все условия выполнены. Он станет опорой для макетов и серверной обработки.',
'В сценарии есть действия пользователя и действия системы. Их нельзя смешивать. Анна вводит мотивацию, но не назначает себе номер заявки и итоговый статус. Система создаёт эти сведения по правилам. Такое разделение сразу помогает определить, какие поля нужны в форме, а какие должны появиться только после обработки.','Отмечайте смену исполнителя между шагами.'),
S('Альтернативные ситуации','Отказ должен сохранять смысл пользовательского пути',T(['Условие','Поведение системы','Что видит Анна'],[['49 символов','Отказ в создании','Уточнение минимальной длины'],['Заявка уже существует','Новой записи нет','Сообщение и переход к своей заявке'],['Проект закрыт','Новая подача запрещена','Объяснение закрытого набора'],['Ответ не получен','Результат ещё не подтверждён','Сохранённый текст и повторная проверка']]),
'Альтернативная ситуация появляется, когда условие основного пути не выполнено или результат нельзя подтвердить. Для каждой ситуации нужно описать поведение системы и понятную обратную связь. Слишком короткий текст можно исправить. Повторную заявку исправлять увеличением текста бессмысленно: нужно открыть существующую. Закрытый проект требует объяснения другого ограничения. Обрыв связи отличается от этих отказов: он может произойти после сохранения.',
'Поэтому одно универсальное сообщение «Произошла ошибка» не подходит всем случаям. Оно скрывает дальнейшее действие пользователя. Мы заранее проектируем различия, чтобы интерфейс и сервер возвращали согласованный смысл. На следующих занятиях каждое сообщение получит свой макет и пример результата обработки.','Отдельно остановитесь на неопределённом результате связи.'),
S('Повторная заявка','Одна комбинация студента и проекта соответствует одной заявке',T(['Студент','Проект','Результат'],[['12','17','Первая заявка допустима'],['12','17','Повтор запрещён'],['12','Другой проект','Отдельная заявка допустима']]),
'Правило повтора относится к сочетанию двух значений. Если Анна уже подала заявку на проект семнадцать, новая заявка на тот же проект не создаётся. Причиной повтора может быть задержка ответа, обновление страницы или другая вкладка. Нам важно сохранить единую запись независимо от причины. В интерфейсе можно временно отключить кнопку, однако само ограничение должно поддерживаться системой. На третьем занятии разберём одновременные запросы и роль базы.',
'Запрет не распространяется на другие проекты. Также в первой версии нет повторного рассмотрения после итогового решения. Если заявка отклонена, она остаётся той же заявкой с итоговым статусом. Мы не вводим скрытое правило, по которому отказ автоматически разрешает новую подачу на тот же проект.','Покажите совпадающую пару в первых двух строках.'),
S('Закрытый проект','Закрытие прекращает приём новых заявок',P(['Открытый проект','При выполнении остальных условий заявка создаётся'],['Закрытый проект','Новая заявка не создаётся'],['Существующая заявка','Сохраняется и остаётся доступной своему владельцу']),
'Состояние проекта определяет возможность новой подачи. Если проект закрыт, система отказывает до создания заявки. При этом сохранённые обращения продолжают существовать. Наше правило не отменяет их и не назначает всем автоматический отказ. Это важное различие между состоянием проекта и состоянием отдельной заявки. На экране карточки можно показать отметку закрытого набора, но сервер всё равно должен проверить актуальное условие при обработке.',
'Представим, что Анна открыла форму до закрытия проекта, а отправила её после. Ранее загруженный экран может содержать устаревшие сведения. Окончательное решение о допустимости новой заявки принимает обработка текущего состояния. Позже мы сопоставим этот случай с серверной проверкой и ожидаемым отказом.','Не обещайте автоматического изменения уже поданных заявок.'),
S('Права пользователей','Студент видит своё, преподаватель рассматривает собственные проекты',T(['Действие','Студент','Преподаватель'],[['Каталог проектов','Да','Не является обязательным сценарием'],['Свои заявки','Да','Нет роли студента в этом сценарии'],['Заявки на проект','Нет общего доступа','Только свой проект'],['Итоговое решение','Нет','Только свой проект']]),
'Матрица прав связывает действие с ролью и дополнительным условием. Слова «преподавателю разрешено» недостаточно. Необходимо уточнить, что проект принадлежит именно этому преподавателю. Ирина может рассматривать обращения к проекту семнадцать, потому что отвечает за него. Другой преподаватель таким правом не обладает. Анна видит собственные заявки, но не получает полномочия принять свою заявку или читать мотивации других студентов.',
'В таблице отсутствие обязательного сценария отличается от универсального технического запрета. Мы описываем согласованную первую версию. На сервере для защищённых операций понадобятся и роль, и проверка принадлежности. Сокрытие кнопки помогает интерфейсу, но не заменяет этих правил. Подробную последовательность проверок рассмотрим отдельно.','Прочитайте условие «только свой проект» полностью.'),
S('Состояния заявки','Три согласованных значения имеют разные значения для пользователя',T(['В данных','На экране','Смысл'],[['pending','На рассмотрении','Решение ещё не принято'],['accepted','Одобрена','Преподаватель принял положительное решение'],['rejected','Отклонена','Преподаватель принял отрицательное решение']]),
'Состояние заявки выражает этап её рассмотрения. После создания система назначает pending, на экране это «На рассмотрении». После положительного решения используется accepted, по-русски «Одобрена». После отрицательного решения — rejected, «Отклонена». Английские значения понадобятся для согласованных данных и API, то есть программного интерфейса обмена, который подробно введём на третьем занятии. Пользователь видит понятные русские подписи.',
'Статусы не описывают сетевую загрузку страницы. Надпись «Отправляем заявку» означает работу интерфейса, а не четвёртое состояние заявки. До сохранения объект может вообще не существовать. Сохранение этого различия позволит корректно объяснить ошибки связи и повторную проверку результата.','Произношение: «пэндинг», «эксэптэд», «риджэктэд».'),
S('Допустимые переходы','Из ожидания рассмотрения возможен один из двух итогов',D(['На рассмотрении','Одобрена','Отклонена'],[['На рассмотрении','Одобрена','Положительное решение'],['На рассмотрении','Отклонена','Отрицательное решение']]),'Из исходного состояния заявка переходит в одно из двух итоговых. На схеме нет обратных связей. Это отражает согласованное правило первой версии: повторное рассмотрение отсутствует. Преподаватель не может сначала одобрить заявку, затем через обычную кнопку изменить её на отклонённую. Если такая возможность понадобится, нужно будет отдельно описать полномочия, причины изменения и последствия для участников. Сейчас мы её не добавляем.',
'Допустимый переход зависит и от текущего состояния, и от права исполнителя. Сам факт существования стрелки не разрешает Анне выполнить операцию. В нашем примере её выполняет Ирина для собственного проекта. При почти одновременных решениях сервер должен опираться на актуальное состояние, чтобы два действия не дали противоречивый итог.','Покажите отсутствие обратных стрелок.'),
S('Итоговые правила заявки','Ограничения образуют согласованный договор проекта',T(['Правило','Значение'],[['Мотивация','50–1000 символов включительно'],['Повтор','Одна заявка студента на проект'],['Приём','Только открытый проект'],['Решение','Своя заявка проекта преподавателя, исходное pending'],['Итог','accepted или rejected, без повторного рассмотрения']]),
'Сведём правила, которые будут действовать во всех следующих материалах. Мотивационный текст имеет обе границы включительно. Одна заявка связывает одного студента и один проект. Закрытый проект новых заявок не принимает. Ирина изменяет статус только в рамках собственного проекта и только из исходного ожидания. Итоговые состояния завершают рассмотрение первой версии. Это единый договор учебного примера, а не универсальные правила всех образовательных сервисов.',
'На следующих занятиях мы будем проверять эти же ограничения в разных представлениях. Поле формы объяснит границы текста. Схема данных покажет сочетание студента и проекта. Серверная обработка свяжет проверки с ответом. Такая последовательность помогает обнаружить противоречие раньше, чем оно превратится в поведение приложения.','Исправьте устно: решение относится к заявке на собственный проект.'),
S('Жизненный цикл ресурса','Решения проходят путь от выяснения задачи до изменения после запуска',P(['Анализ','Проблема, участники, правила и требования'],['Проектирование','Экраны, данные и устройство решения'],['Разработка и проверка','Реализация поведения и поиск несоответствий'],['Выпуск и сопровождение','Доступ пользователям, наблюдение и улучшения']),
'Жизненный цикл описывает работу с ресурсом во времени. Сначала выясняют задачу, затем оформляют решение, реализуют и проверяют его. После выпуска работа продолжается: возникают изменения, ошибки и новые данные о потребностях. Эта схема не требует, чтобы команда делала каждый этап только один раз. Результаты проверки могут вернуть нас к требованиям. Важно понимать назначение работ и их результаты, а не запоминать единственную последовательность для всех проектов.',
'Для «Проектного навигатора» изменение формы может затронуть модель данных и проверку. Поэтому результаты этапов должны оставаться связанными. Мы будем показывать конкретные носители решений: требования, макеты, договор обмена и памятку сопровождения. Они помогают передать смысл следующему участнику работы.','Не представляйте ленту как обязательную универсальную методологию.'),
S('Этап анализа','Результат анализа объясняет, зачем и для кого создают ресурс',T(['Вопрос','Результат для нашего проекта'],[['Какая проблема','Обращения расходятся между источниками'],['Кто использует','Студент и преподаватель'],['Какой результат нужен','Общее сохранённое обращение и понятный статус'],['Какие ограничения','Одна заявка, границы мотивации, свои проекты']]),
'На этапе анализа мы отделяем наблюдаемую проблему от предполагаемого решения. Итог должен быть понятен участникам без чтения программы. Для учебного сервиса уже установлены роли, основные цели и ограничения. Если пропустить этот этап, разработчик может добросовестно сделать форму, которая отправляет письмо, хотя пользователю требовался доступный список заявок. Внешне работа будет похожа, а ожидаемый результат останется недостижимым.',
'Анализ не завершается количеством заполненных страниц. Его качество видно по устранённым существенным неопределённостям. Мы знаем, что считается повтором, кто вправе принять решение и что происходит после закрытия проекта. Именно такие сведения позволяют дальше проектировать согласованные экраны и данные.','Сопоставляйте каждый вопрос с уже готовым результатом.'),
S('Этап проектирования','Решения связывают требования с интерфейсом и данными',P(['Пользовательский путь','Где Анна выбирает проект и видит результат'],['Модель данных','Как связаны пользователь, проект и заявка'],['Обработка','Кто проверяет правила и сохраняет изменения']),
'Проектирование преобразует требования в решения, по которым можно создать ресурс. Для Анны определим набор экранов и обратную связь. Для хранения сведений выберем структуру связанных записей. Для обработки опишем ответственность частей приложения. Решения должны поддерживать один сценарий. Например, если макет показывает дату подачи, необходимо определить, откуда эта дата появляется. Нельзя просто добавить красивую строку без источника значения.',
'На этом этапе допустимы варианты. Можно сравнить два расположения сообщения об ошибке или два способа навигации. Выбор объясняют задачей пользователя и ограничениями. На втором занятии мы пройдём такой путь для формы заявки и получим готовую модель данных.','Проектное решение сопровождайте причиной его выбора.'),
S('Этап разработки','Программа реализует согласованные правила и представления',P(['Интерфейс','Показывает каталог, форму и состояния'],['Обработка на сервере','Проверяет пользователя и бизнес-правила'],['Работа с данными','Сохраняет заявку и решение преподавателя']),
'На этапе разработки проектные решения превращают в исполняемую программу. Разные части могут создавать разные специалисты, но правила остаются общими. Если интерфейс допускает текст до тысячи символов, а сервер принимает только пятьсот, пользователю достанется противоречие. Если база хранит произвольные статусы, обработка может получить неподдерживаемое значение. Поэтому реализация должна опираться на согласованный договор.',
'В вебинарах не требуется писать программу в прямом эфире. Вместо этого на третьем занятии увидим подготовленные запросы, ответы и последовательность обработки. Такой формат позволяет разобрать причинную связь каждого шага, не тратя время на настройку инструментов и исправление опечаток.','Не запускайте обязательную демонстрацию программирования.'),
S('Этап проверки','Согласованные условия сопоставляют с поведением реализации',T(['Условие','Ожидаемый результат'],[['Анна подаёт допустимую первую заявку','Появляется одна запись pending'],['Анна повторяет подачу','Вторая запись не возникает'],['Другой преподаватель меняет решение','Система отказывает']]),
'Проверка связывает требование с наблюдаемым поведением программы. Сначала задают исходные условия, затем выполняют действие и сравнивают результат с ожидаемым. Ожидаемый результат выводится из правил проекта. Фактический результат получают только при выполнении проверки на реализации. На этом слайде мы показываем подготовленные ожидания. Мы ещё не утверждаем, что действующее приложение успешно прошло эти проверки.',
'Разница между ожиданием и наблюдением существенна для доверия к отчёту. Заполненная таблица сама по себе ничего не доказывает о работающей программе. На четвёртом занятии разберём виды проверок, границы длины и оформление несоответствий. Сейчас фиксируем место проверки в жизненном цикле и её связь с требованиями.','Явно назовите таблицу ожидаемыми результатами.'),
S('Развёртывание','Подготовленная версия становится доступна в рабочей среде',P(['Подготовка','Настройки приложения и доступ к хранилищу'],['Публикация','Запуск выбранной версии по рабочему адресу'],['Подтверждение','Проверка доступности и основного пути заявки']),
'Развёртывание означает размещение и запуск подготовленной версии в среде, где ею будут пользоваться. На компьютере разработчика программа может работать с отдельными учебными данными. Рабочая среда имеет собственные настройки и хранилище. Поэтому простое копирование файлов не гарантирует готовности. Нужно убедиться, что компоненты связаны и основные действия доступны. Подробный порядок выпуска рассмотрим вместе с инфраструктурой на третьем занятии.',
'Для проектирования важно заранее знать условия использования. Если ресурс должен работать через браузер по общему адресу, эта потребность влияет на размещение. Однако мы не выбираем конкретного поставщика только по названию этапа. Устройство и стоимость соотносят с объёмом задачи и возможностями сопровождения.','Произношение слова «развёртывание» не требует англоязычного сокращения.'),
S('Сопровождение','После запуска ресурс требует наблюдения и обновлений',P(['Обнаружение','Участник сообщает о проблеме или система показывает отклонение'],['Разбор','Команда сопоставляет действия, состояние и технические сведения'],['Исправление','Изменение проверяют и выпускают управляемо']),
'Сопровождение поддерживает пригодность ресурса после выпуска. Пользователи могут столкнуться с непредусмотренной ситуацией, объём каталога может вырасти, а зависимый сервис — стать недоступным. Чтобы реагировать предметно, нужны сведения о работе системы и понятный порядок изменений. На четвёртом занятии разберём случай, когда заявка сохранена, но подтверждение не дошло. Он покажет, почему сообщение пользователя нужно связывать с состоянием данных.',
'Сопровождение не сводится к постоянному переписыванию программы. Иногда достаточно объяснения, восстановления связи или исправления настройки. В каждом случае полезно знать границу ответственности и критерий восстановления. Поэтому памятка сопровождения входит в комплект результатов проекта вместе с экранами и моделью данных.','Не добавляйте новую роль пользователя для технического сопровождения.'),
S('Изменение требований после запуска','Новое пожелание проходит оценку влияния',P(['Пожелание','Студент хочет приложить файл с примерами работ'],['Оценка','Меняются форма, хранение, ограничения и сопровождение'],['Решение','Функцию принимают в план или обоснованно откладывают']),
'После запуска знания о потребностях уточняются. Это естественно, но изменение нужно оценивать целиком. Просьба добавить одну кнопку может затронуть несколько частей системы. Мы проверяем пользу, зависимые решения, дополнительные ограничения и способ приёмки. Если просто изменить экран, остальные части окажутся неподготовленными. В конце занятия подробно пройдём такое изменение на примере вложений.',
'Изменение не обнуляет уже согласованные решения. Необходимо явно указать, какие правила сохраняются, а какие меняются. Например, добавление файла само по себе не должно менять число заявок на один проект. Связи требований с данными и обработкой помогают увидеть эту границу и избежать случайных последствий.','Свяжите с будущим разбором вложений, не раскрывая его повторно.'),
S('Состав первой версии','Полный основной путь важнее числа функций',T(['Необходимая возможность','Почему входит'],[['Каталог и карточка','Анна должна выбрать проект'],['Форма заявки','Анна передаёт мотивацию'],['Мои заявки','Анна видит подтверждение и итог'],['Рассмотрение преподавателем','Ирина завершает процесс решением']]),
'Первая версия должна позволять пройти согласованный путь до полезного результата. Если оставить только каталог, Анна не сможет подать заявку. Если оставить форму без списка преподавателя, обращение некому рассмотреть. Поэтому состав версии определяют связностью действий. Каждая возможность на экране закрывает необходимый шаг. Такой подход помогает не сокращать продукт до внешне законченной, но практически бесполезной части.',
'В нашем учебном варианте каталог заранее заполнен, а вход уже действует. Это зафиксированные допущения. Мы можем сосредоточиться на создании и рассмотрении заявки, не добавляя редактор проектов. Полнота оценивается относительно выбранного сценария и границ, а не относительно всех возможностей похожих сервисов.','Читайте таблицу через причину включения функции.'),
S('Отложенные возможности','Расширение требует отдельной пользы и проектирования',T(['Пожелание','Причина отложить'],[['Чат','Основное решение принимают без переписки внутри сервиса'],['Вложения','Нужны новые правила файлов и хранения'],['Видеовстречи','Не входят в путь регистрации заявки'],['Подбор проектов','Сначала нужен устойчивый базовый каталог']]),
'Отложенная возможность остаётся за границей первой версии по конкретной причине. Чат может быть полезен, но для регистрации и решения достаточно мотивационного текста. Вложения требуют дополнительных ограничений, которые ещё не определены. Подбор проектов будем рассматривать как развитие после появления понятного базового пути. Мы сохраняем пожелания, чтобы не потерять идею, однако не считаем их уже реализованными или согласованными.',
'Такое разделение делает объём проекта обозримым. Когда позже обсуждается поиск по интересам, мы явно назовём его расширением. В исходных таблицах не появятся скрытые поля интересов или файлов. Это позволит оценить, какие изменения действительно необходимы новой функции, и сравнить пользу с дополнительной сложностью.','Не называйте отложенные функции ошибочными.'),
S('Общая архитектура','Браузер показывает, сервер применяет правила, база хранит',D(['Браузер','Сервер','База данных'],[['Браузер','Сервер','Запрос'],['Сервер','База данных','Чтение и сохранение'],['Сервер','Браузер','Ответ']]),
'Архитектура описывает существенные части приложения и их взаимодействия. В нашей учебной схеме три части. Браузер показывает форму и результат. Сервер получает обращение и проверяет правила. База хранит пользователей, проекты и заявки. Связи идут через сервер: браузер не получает прямое право произвольно менять таблицы. Пока схема не задаёт число компьютеров или процессов. Она распределяет ответственность.',
'Такое разделение объясняет, почему одна и та же проверка может иметь разные задачи. В браузере ограничение длины помогает человеку быстро исправить текст. На сервере проверка определяет допустимость обращения. В базе ограничения защищают согласованность записей. Эти действия поддерживают одно правило на разных границах.','Прочитайте названия частей и ответственность каждой.'),
S('Браузер','Интерфейс помогает выполнить действие и понять результат',P(['Ввод','Анна видит выбранный проект и пишет мотивацию'],['Обратная связь','Форма показывает ограничение и ошибки заполнения'],['Результат','Страница отображает подтверждённые сведения системы']),
'Браузерная часть отвечает за взаимодействие с пользователем. Она должна понятно показать задачу, дать ввести мотивацию и объяснить полученный результат. Часть ошибок удобно обнаружить до отправки. Например, подсказка длины избавляет от бесполезного ожидания. Но браузер работает с теми сведениями, которые уже получил. Если проект закрыли после открытия страницы, локальная копия может устареть. Поэтому окончательные правила проверяет сервер.',
'Не будем поручать интерфейсу выбор итогового статуса или номера студента. Пользователь не должен заполнять технические значения, которые система уже знает. Во втором вебинаре покажем, как такое распределение отражается в форме: поле мотивации будет единственным необходимым пользовательским вводом для выбранного проекта.','Отличайте удобство ввода от окончательного решения системы.'),
S('Сервер','Обработка связывает пользователя, правила и сохранение',P(['Пользователь','Определяется по действующему сеансу'],['Проверки','Роль, проект, текст, повтор и допустимый переход'],['Изменение','Сохранение согласованного результата и подготовка ответа']),
'Серверная часть получает обращения от браузера и действует от имени установленного пользователя. Сеанс — способ связать последовательность обращений с уже выполненным входом. В нашем курсе вход работает заранее. Сервер проверяет правила независимо от того, какие элементы видны на странице. Анна может изменить отправляемые данные, поэтому поле с её номером не является доказательством личности. Проверку полномочий нельзя заменить скрытой кнопкой.',
'После проверок сервер организует работу с данными и формирует результат. Для успешной подачи он должен подтвердить именно сохранение. При отказе — сообщить согласованную причину. На третьем занятии разложим эту обработку на короткие шаги и покажем реальные форматы обмена без обязательного программирования в эфире.','Сеанс произносится обычным словом, объясните его назначение.'),
S('База данных','Связанные записи сохраняют общее состояние ресурса',T(['Сущность','Пример сохраняемых сведений'],[['Пользователь','Анна, роль студент, id 12'],['Проект','Название, преподаватель 7, доступность набора'],['Заявка','Проект 17, студент 12, мотивация, статус']]),
'База данных хранит организованные сведения, которые приложение получает и изменяет. Для нашего проекта достаточно трёх основных сущностей: пользователя, проекта и заявки. Заявка связывает существующего студента с существующим проектом. Мы не копируем в каждое обращение всё описание проекта. При чтении приложение получает необходимые связанные сведения. Подробно ключи и ограничения разберём на втором занятии.',
'Хранение общего состояния позволяет Анне закрыть страницу и позже увидеть ту же заявку. Оно также позволяет Ирине рассмотреть обращение независимо от открытого окна студента. Однако само наличие базы не гарантирует согласованность. Нужно определить обязательные поля, допустимые значения и запрет повторной пары. Поэтому схема данных является частью проектирования.','Не превращайте таблицу в подробную схему полей раньше второго вебинара.'),
S('Принцип выбора технологий','Инструмент соответствует задаче и условиям сопровождения',T(['Критерий','Что выясняем'],[['Функциональность','Можно ли реализовать выбранные экраны и правила'],['Данные','Есть ли нужные связи и ограничения'],['Команда','Кто сможет поддерживать решение'],['Размещение','Где и как будет работать ресурс']]),
'Технологии выбирают после понимания задачи и ограничений. Для учебного сервиса важны приём обращений, проверка прав и согласованное хранение. Можно реализовать это разными языками и средствами. Название популярного инструмента ещё не объясняет его пригодность. Учитывают возможности команды, среду размещения и будущие изменения. Слишком сложное решение увеличит стоимость поддержки, если его преимущества не нужны выбранному сценарию.',
'В курсе мы используем HTTP, JSON и короткие примеры SQL как форматы, необходимые для объяснения обмена и данных. Названия языков здесь обозначают инструменты разбора, а не обязательный промышленный стек. Все серверные алгоритмы будут явно помечены как псевдокод, чтобы ведущему не пришлось переключаться между несколькими языками.','Не назначайте конкретный стек без основания в задаче.'),
S('Риски и зависимости','Неопределённость оценивают до начала реализации',T(['Риск или зависимость','Последствие','Ответное решение'],[['Неясное правило повторов','Две несовместимые реализации','Зафиксировать пару студент и проект'],['Готовый вход','Без него нельзя определить пользователя','Записать допущение и границу'],['Изменение проекта после открытия формы','Устаревшие сведения интерфейса','Повторная серверная проверка']]),
'Риск — возможное событие, которое помешает цели. Зависимость — условие или результат другой работы, без которого наш сценарий не выполнится. Мы уже зависим от действующего входа. Если это допущение неверно, объём проекта изменится. Неясность правила повторов тоже создаёт риск: интерфейс и сервер могут запретить разные действия. Раннее уточнение стоит дешевле, чем согласование нескольких готовых реализаций.',
'Реестр рисков полезен, если у каждой записи есть последствие и ответное решение. Общая строка «возможны ошибки» ничего не подсказывает. В таблице условия конкретны и связаны с нашим примером. По ним можно понять, что необходимо уточнить, что проверить и какое допущение передать следующему участнику проекта.','Различайте риск и уже наступившую ошибку.'),
S('Связь требований и решений','Одна потребность прослеживается до экрана, данных и проверки',T(['Основание','Проектное решение','Проверка'],[['ФТ-01: видеть сохранённую заявку','Раздел «Мои заявки» и запись в базе','После подачи видна нужная заявка'],['ПР-01: одна заявка на проект','Уникальная пара студента и проекта','Повтор не создаёт запись'],['ПР-03: только свой проект','Проверка принадлежности на сервере','Чужой преподаватель получает отказ']]),
'Прослеживаемость означает возможность пройти от потребности к связанному решению и обратно. Если в форме появляется новое поле, должно быть понятно, какую задачу оно поддерживает. Если требование существует только в документе, но нигде не реализовано, связь оборвана. На экране показаны три законченные цепочки. Они объединяют разные виды материалов вокруг одного правила. Это помогает оценить полноту проектирования.',
'Представим, что мы меняем правило повторной подачи. Тогда нужно пересмотреть ограничение данных, обработку, сообщение и проверку. Связи позволяют найти эти места адресно. Без них команда будет искать по памяти и рискует оставить старое правило в одной из частей. Позже эта же идея поможет проверить весь комплект вебинаров.','Читайте строки слева направо, не по отдельным столбцам.'),
S('Паспорт проекта','Краткое согласованное описание первой версии',T(['Раздел','Заполненный результат'],[['Название','Проектный навигатор'],['Цель','Единый учёт подачи и рассмотрения заявок'],['Роли','Студент, преподаватель'],['Состав','Каталог, подача, свои заявки, решение'],['Ограничения','50–1000 символов, одна заявка, свой проект'],['Вне версии','Чат, вложения, видео, интеллектуальный поиск']]),
'Паспорт проекта собирает основные договорённости в одном обозримом документе. Он не заменяет подробные требования, но помогает быстро понять назначение и объём. Для «Проектного навигатора» мы можем заполнить его без вымышленных сроков, бюджета и фамилий ответственных за разработку. Известны цель, роли, функции и ограничения. Отложенные возможности записаны явно. Это защищает первую версию от случайного расширения.',
'Паспорт полезно читать вместе со схемой процесса и реестром требований. Краткое слово «подача» раскрывается через условия, действия и подтверждение. Если материалы противоречат друг другу, требуется согласовать исходное решение. Декоративно оформленный паспорт с неподтверждёнными обещаниями не заменяет такой работы.','Показывайте заполненный документ, не оставляйте поля для аудитории.'),
S('Запрос на добавление вложений','Новая кнопка означает изменение пути работы с данными',P(['Пожелание','Анна хочет приложить примеры своих работ'],['Польза','Ирина сможет посмотреть дополнительные материалы'],['Изменение','Появится файл со своими правилами обработки и хранения']),
'Разберём готовый запрос на изменение: к мотивационному тексту предлагают добавить файл с примерами работ. Польза понятна — преподаватель сможет увидеть результат предыдущей деятельности. Однако формулировка ещё не задаёт допустимые форматы, размер и срок хранения. Если сразу нарисовать кнопку загрузки, мы создадим впечатление согласованного решения. Поэтому сначала определим новые объекты и действия, которые появятся в системе.',
'Вложения в этом разборе рассматриваются как предложение следующей версии. Они не включаются в исходную заявку и не изменяют схемы второго вебинара. Мы используем один пример изменения, чтобы показать оценку влияния, а не незаметно увеличить состав проекта. После разбора будет принято явное решение о границе версии.','На слайде пометьте вложения как предложение, а не базовую функцию.'),
S('Затрагиваемые части системы','Файл проходит через интерфейс, обработку и хранение',D(['Форма заявки','Серверная обработка','Хранилище файлов','Данные заявки'],[['Форма заявки','Серверная обработка','Передача файла'],['Серверная обработка','Хранилище файлов','Сохранение содержимого'],['Серверная обработка','Данные заявки','Связь с файлом']]),
'Для вложения понадобится элемент выбора файла в форме. Серверу нужно принять содержимое и проверить ограничения. Сам файл придётся хранить, а в заявке — поддержать связь с ним. Преподавателю понадобится возможность открыть допустимое вложение. Кроме счастливого пути возникают ошибки передачи и недоступность хранилища. Таким образом, изменение затрагивает почти весь путь данных, хотя пользователь начинает его одной кнопкой.',
'На схеме специально показано отдельное хранилище как проектный вариант для оценки, а не как утверждённая архитектура базовой версии. Выбор конкретного способа хранения потребовал бы дополнительных решений. Сейчас достаточно увидеть новые обязанности и зависимость между сохранением заявки и сохранением файла.','Отметьте статус схемы: оценка предлагаемого расширения.'),
S('Новые правила для файлов','До реализации необходимо согласовать допустимость и доступ',T(['Вопрос','Что требуется определить'],[['Формат','Какие типы содержимого разрешены'],['Размер','Какова граница и сообщение при превышении'],['Доступ','Кто открывает файл и как проверяют право'],['Хранение','Как долго сохраняют и как удаляют'],['Ошибка','Что происходит с заявкой при сбое передачи']]),
'Новое поле требует новых правил. Нужно согласовать, какие файлы действительно помогают преподавателю, какой объём допустим и кто имеет доступ. Ошибка загрузки может случиться до или после сохранения заявки, поэтому потребуется определить поведение в обоих случаях. Нельзя оставлять решение на случайное поведение браузера. Даже если библиотека умеет загружать файл, она не выбирает за проектировщика смысл этой операции.',
'Мы не заполняем таблицу произвольными числами. На слайде показан перечень решений, необходимых для оценки предложения. В отличие от мотивационного текста с утверждённой границей, параметры вложений пока не согласованы. Это позволяет честно показать неопределённость и не выдавать предположение за действующее правило курса.','Не придумывайте размер файла как утверждённое ограничение.'),
S('Дополнительная сложность','Нужно учитывать отказ, проверку доступа и сопровождение файла',P(['Подача','Обработка должна связать результат двух сохранений'],['Рассмотрение','Преподаватель получает только доступные ему вложения'],['Сопровождение','Нужно понимать, где файл, заявка и причина сбоя']),
'Оценим сложность по последствиям. Если файл сохранился, а заявка нет, возникнет лишнее содержимое. Если заявка сохранилась, а файл недоступен, преподавателю потребуется понятное сообщение. Проверка прав должна действовать и при открытии вложения по прямому адресу. Сопровождение должно различать отсутствие файла и отказ доступа. Эти ситуации показывают, почему объём расширения нельзя оценить только временем рисования кнопки.',
'Дополнительная сложность не означает, что функцию никогда нельзя делать. Она означает необходимость обоснованного выбора и полного проектирования. Польза должна сопоставляться с затратами и рисками. Для нашей первой версии основной путь уже завершён без вложений, поэтому есть возможность отложить эту работу без потери цели.','Сравните последствия по этапам пути файла.'),
S('Решение отложить вложения','Первая версия принимает только мотивационный текст',T(['Критерий','Оценка'],[['Основной путь','Выполняется без файла'],['Правила файлов','Ещё не согласованы'],['Влияние','Форма, сервер, данные, хранение, сопровождение'],['Решение','Сохранить пожелание для отдельного расширения']]),
'После оценки принимаем конкретное решение: вложения остаются за границей первой версии. В форме будет только мотивационный текст, связанный с выбранным проектом. Пожелание сохраняется отдельно с описанной пользой и вопросами для уточнения. Такое решение можно объяснить заинтересованным сторонам. Оно основано на достаточности основного пути и несогласованной сложности расширения. Это лучше, чем обещание без понятного объёма.',
'На следующих занятиях отсутствие файла является следствием данного решения. В структуре заявки не будет скрытого поля вложения. Договор создания заявки не станет требовать загрузку. Когда функция вернётся в план, мы сможем оценить изменение относительно устойчивой основы и проследить все затронутые части.','Подчеркните окончательную границу учебной первой версии.'),
S('Комплект результатов проектирования','Паспорт, процесс, требования и правила согласованы между собой',P(['Назначение','Паспорт фиксирует цель, роли и состав версии'],['Поведение','Процесс и сценарии показывают действия и исключения'],['Договор','Требования, права и статусы задают проверяемые ограничения'],['Следующий шаг','Экраны и данные должны поддержать эти решения']),
'Мы получили согласованное описание будущего ресурса. Паспорт задаёт назначение и границы. Модель процесса показывает путь заявки. Требования уточняют, что должна делать система и как проверить результат. Права и состояния определяют допустимые действия. Эти материалы можно передать следующему участнику проекта без необходимости самостоятельно угадывать правило повторов или смысл закрытого набора.',
'Мы определили, какие действия должна поддерживать система. Теперь необходимо показать, как пользователь выполнит эти действия на экране и какие данные приложение должно для этого хранить. На втором вебинаре перейдём к конкретным макетам, объектам и таблицам. Все решения будут опираться на уже согласованный путь Анны и Ирины.','Завершите готовым переходом. Не добавляйте вопросы аудитории.')
];
